\documentclass[tikz, border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}

\begin{document}
	\pagestyle{empty} %% IMPORTANT	

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\begin{tikzpicture}

	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=black, thick},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	axis equal,
	xmin = -1.5,
	xmax = 1.5,
	ymin = -2.5,
	ymax = 1.5,
	xtick = {-2,2},
	ytick = {-1,1},
	%x tick label style={xshift={(\tick==-2)*-8pt}},
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	%%Tangent%%
	\draw[very thick, orangepeel] (axis cs:0,-0.5) -- (axis cs:0,0.5);

	\plot[data cs=polar, domain=0:180, samples=360, deepskyblue, very thick]({\x}, {cos(\x)*cos(\x)});
	\node[deepskyblue!80!black] at (axis cs:1,1.25) {\small $r=\cos^2\theta$};

	\node[circle, inner sep=1.5pt, fill=orangepeel, label={below left:$\theta=\frac{\pi}{2}$}] at (axis cs:0,0) {};

	\end{axis}
	\end{tikzpicture}
\end{document}

